#include <cstdint>
#include <iostream>
#include <vector>

static int log2exact(std::uint64_t v)
{
    int k{ 0 };
    while (v > 1) { v >>= 1; ++k; }
    return k;
}

int main()
{
    std::uint64_t cacheBytes{}, assoc{}, blockBytes{};
    int addrBits{};
    int q{};
    if (!(std::cin >> cacheBytes >> assoc >> blockBytes >> addrBits >> q)) return 0;

    const std::uint64_t sets{ cacheBytes / (assoc * blockBytes) };
    const int offsetBits{ log2exact(blockBytes) };
    const int indexBits{ log2exact(sets) };
    const int tagBits{ addrBits - offsetBits - indexBits };

    std::cout << "geometry sets " << sets
              << " offsetbits " << offsetBits
              << " indexbits " << indexBits
              << " tagbits " << tagBits << "\n";

    const std::uint64_t offsetMask{ blockBytes - 1 };
    const std::uint64_t indexMask{ sets - 1 };

    std::vector<std::uint64_t> idx;
    for (int i = 0; i < q; ++i)
    {
        std::uint64_t a{};
        std::cin >> a;

        std::uint64_t offset{ a & offsetMask };
        std::uint64_t index{ (a >> offsetBits) & indexMask };
        std::uint64_t tag{ a >> (offsetBits + indexBits) };

        std::cout << a << " offset " << offset
                  << " index " << index
                  << " tag " << tag << "\n";
        idx.push_back(index);
    }

    int same{ 0 };
    for (std::size_t i = 1; i < idx.size(); ++i)
        if (idx[i] == idx[i - 1]) ++same;

    std::cout << "sameset " << same << "\n";

    return 0;
}
